var folderFiles = [];
var folderStatus = "idle"; // idle | open | loading | ready | cancelled

var fileFiles = [];
var fileStatus = "idle"; // idle | open | loading | ready | cancelled



// =====================================================
//  FOLDER PICKER (ya lo tenías)
// =====================================================
function folder_open() {
    folderFiles = [];
    folderStatus = "open";

    var input = document.createElement("input");
    input.type = "file";
    input.setAttribute("webkitdirectory", "");
    input.setAttribute("directory", "");

    var settled = false;

    function settleCancel() {
        if (settled) return;
        if (folderStatus === "loading" || folderStatus === "ready") return;
        settled = true;
        folderFiles = [];
        folderStatus = "cancelled";
    }

    function settleReady(list) {
        settled = true;
        folderFiles = list;
        folderStatus = "ready";
    }

    input.addEventListener("cancel", settleCancel);

    input.onchange = async function (ev) {
        if (folderStatus === "ready" || folderStatus === "cancelled") return;
        folderStatus = "loading";

        var files = ev.target && ev.target.files;
        if (!files || files.length === 0) {
            settled = false;
            folderStatus = "open";
            settleCancel();
            return;
        }

        try {
            var list = [];
            for (var i = 0; i < files.length; i++) {
                var file = files[i];
                list.push({
                    name: file.name,
                    path: file.webkitRelativePath || file.name,
                    dataUrl: await readFileAsDataURL(file)
                });
            }
            settleReady(list);
        } catch (err) {
            console.error(err);
            settled = false;
            folderStatus = "open";
            settleCancel();
        }
    };

    input.click();
}

// =====================================================
//  FILE PICKER (NUEVO - un solo archivo)
// =====================================================
function file_open(accept) {
    fileFiles = [];
    fileStatus = "open";

    var input = document.createElement("input");
    input.type = "file";
    if (accept && accept !== "") {
        input.accept = accept; // ejemplo: ".save,text/plain"
    }

    var settled = false;

    function settleCancel() {
        if (settled) return;
        if (fileStatus === "loading" || fileStatus === "ready") return;
        settled = true;
        fileFiles = [];
        fileStatus = "cancelled";
    }

    function settleReady(list) {
        settled = true;
        fileFiles = list;
        fileStatus = "ready";
    }

    input.addEventListener("cancel", settleCancel);

    input.onchange = async function (ev) {
        if (fileStatus === "ready" || fileStatus === "cancelled") return;
        fileStatus = "loading";

        var files = ev.target && ev.target.files;
        if (!files || files.length === 0) {
            settled = false;
            fileStatus = "open";
            settleCancel();
            return;
        }

        try {
            var list = [];
            for (var i = 0; i < files.length; i++) {
                var file = files[i];
                list.push({
                    name: file.name,
                    path: file.name,
                    dataUrl: await readFileAsDataURL(file)
                });
            }
            settleReady(list);
        } catch (err) {
            console.error(err);
            settled = false;
            fileStatus = "open";
            settleCancel();
        }
    };

    input.click();
}

// =====================================================
//  UTILIDAD COMÚN
// =====================================================
function readFileAsDataURL(file) {
    return new Promise(function (resolve, reject) {
        var reader = new FileReader();
        reader.onload = function (e) { resolve(e.target.result); };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

// =====================================================
//  API FOLDER (igual que antes)
// =====================================================
function folder_get_status() {
    return String(folderStatus || "idle");
}

function folder_is_ready() {
    return folderStatus === "ready" ? 1 : 0;
}

function folder_was_cancelled() {
    return folderStatus === "cancelled" ? 1 : 0;
}

function folder_file_count() {
    return folderFiles.length;
}

function folder_get_name(index) {
    index = Number(index);
    if (index < 0 || index >= folderFiles.length) return "";
    return folderFiles[index].name;
}

function folder_get_path(index) {
    index = Number(index);
    if (index < 0 || index >= folderFiles.length) return "";
    return folderFiles[index].path;
}

function folder_get_data(index) {
    index = Number(index);
    if (index < 0 || index >= folderFiles.length) return "";
    return folderFiles[index].dataUrl;
}

function folder_clear() {
    folderFiles = [];
    folderStatus = "idle";
}

// =====================================================
//  API FILE (NUEVO)
// =====================================================
function file_get_status() {
    return String(fileStatus || "idle");
}

function file_is_ready() {
    return fileStatus === "ready" ? 1 : 0;
}

function file_was_cancelled() {
    return fileStatus === "cancelled" ? 1 : 0;
}

function file_file_count() {
    return fileFiles.length;
}

function file_get_name(index) {
    index = Number(index);
    if (index < 0 || index >= fileFiles.length) return "";
    return fileFiles[index].name;
}

function file_get_path(index) {
    index = Number(index);
    if (index < 0 || index >= fileFiles.length) return "";
    return fileFiles[index].path;
}

function file_get_data(index) {
    index = Number(index);
    if (index < 0 || index >= fileFiles.length) return "";
    return fileFiles[index].dataUrl;
}

function file_clear() {
    fileFiles = [];
    fileStatus = "idle";
}
function downloadTextFile(filename, text) {
    try {
        var blob = new Blob([text], { type: "text/plain;charset=utf-8" });
        var url = URL.createObjectURL(blob);
        var a = document.createElement("a");
        a.href = url;
        a.download = filename || "savegame.save";
        a.style.display = "none";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(function () { URL.revokeObjectURL(url); }, 2000);
        return 1;
    } catch (e) {
        console.error(e);
        return 0;
    }
}


// =====================================================
//  TEXT INPUT - versión manual (GameMaker HTML5)
// =====================================================

var textInputValue = "";
var textInputStatus = "idle"; // idle | open | ready | cancelled
var textInputElement = null;
var textInputRef = null;
var textInputKeyHandler = null;
var textInputPasteHandler = null;
var textInputCanvas = null;
var textInputOldPointerEvents = "";

function text_input_open(defaultText, placeholder, inputType) {
    textInputValue = String(defaultText || "");
    textInputStatus = "open";
    text_input_destroy_ui();

    // Evitar que el canvas robe clicks
    textInputCanvas = document.getElementById("canvas") || document.querySelector("canvas");
    if (textInputCanvas) {
        textInputOldPointerEvents = textInputCanvas.style.pointerEvents;
        textInputCanvas.style.pointerEvents = "none";
    }

    var container = document.createElement("div");
    container.style.position = "fixed";
    container.style.left = "50%";
    container.style.top = "14%";
    container.style.transform = "translateX(-50%)";
    container.style.zIndex = "2147483647";
    container.style.background = "#1a1a24";
    container.style.padding = "18px";
    container.style.borderRadius = "12px";
    container.style.border = "3px solid #50b4ff";
    container.style.boxShadow = "0 12px 40px rgba(0,0,0,0.85)";
    container.style.display = "flex";
    container.style.flexDirection = "column";
    container.style.gap = "10px";
    container.style.width = "92%";
    container.style.maxWidth = "480px";
    container.style.fontFamily = "sans-serif";
    container.style.pointerEvents = "auto";

    var label = document.createElement("div");
    label.innerText = String(placeholder || "Type here...");
    label.style.color = "#9ad0ff";
    label.style.fontSize = "14px";

    var input = document.createElement("textarea");
    input.value = textInputValue;
    input.placeholder = String(placeholder || "Type here...");
    input.rows = 3;
    input.autocomplete = "off";
    input.autocapitalize = "off";
    input.spellcheck = false;
    input.style.fontSize = "20px";
    input.style.padding = "12px 14px";
    input.style.borderRadius = "8px";
    input.style.border = "2px solid #666";
    input.style.background = "#000";
    input.style.color = "#fff";
    input.style.caretColor = "#50b4ff";
    input.style.outline = "none";
    input.style.width = "100%";
    input.style.boxSizing = "border-box";
    input.style.resize = "vertical";
    input.style.minHeight = "74px";
    input.style.lineHeight = "1.3";
    input.style.pointerEvents = "auto";

    var hint = document.createElement("div");
    hint.innerText = "Select text • Ctrl+C / Ctrl+V / Ctrl+X • Enter=OK • Esc=Cancel";
    hint.style.color = "#888";
    hint.style.fontSize = "12px";

    var buttons = document.createElement("div");
    buttons.style.display = "flex";
    buttons.style.gap = "10px";

    var btnOk = document.createElement("button");
    btnOk.innerText = "OK";
    btnOk.style.flex = "1";
    btnOk.style.padding = "12px";
    btnOk.style.fontSize = "18px";
    btnOk.style.border = "none";
    btnOk.style.borderRadius = "8px";
    btnOk.style.background = "#2ecc71";
    btnOk.style.color = "#fff";
    btnOk.style.cursor = "pointer";

    var btnCancel = document.createElement("button");
    btnCancel.innerText = "Cancel";
    btnCancel.style.flex = "1";
    btnCancel.style.padding = "12px";
    btnCancel.style.fontSize = "18px";
    btnCancel.style.border = "none";
    btnCancel.style.borderRadius = "8px";
    btnCancel.style.background = "#e74c3c";
    btnCancel.style.color = "#fff";
    btnCancel.style.cursor = "pointer";

    buttons.appendChild(btnOk);
    buttons.appendChild(btnCancel);

    container.appendChild(label);
    container.appendChild(input);
    container.appendChild(hint);
    container.appendChild(buttons);
    document.body.appendChild(container);

    textInputElement = container;
    textInputRef = input;

    function syncFromInput() {
        textInputValue = input.value || "";
    }

    function setValueKeepCaret(v, caret) {
        input.value = v;
        textInputValue = v;
        try {
            var c = Math.max(0, Math.min(caret, v.length));
            input.setSelectionRange(c, c);
        } catch (e) {}
    }

    function replaceSelection(text) {
        var start = input.selectionStart|0;
        var end = input.selectionEnd|0;
        var v = input.value || "";
        var nv = v.substring(0, start) + text + v.substring(end);
        setValueKeepCaret(nv, start + String(text).length);
    }

    function deleteSelectionOrChar(isBackspace) {
        var start = input.selectionStart|0;
        var end = input.selectionEnd|0;
        var v = input.value || "";

        if (start !== end) {
            var nv = v.substring(0, start) + v.substring(end);
            setValueKeepCaret(nv, start);
            return;
        }

        if (isBackspace) {
            if (start <= 0) return;
            var nv2 = v.substring(0, start - 1) + v.substring(start);
            setValueKeepCaret(nv2, start - 1);
        } else {
            if (start >= v.length) return;
            var nv3 = v.substring(0, start) + v.substring(start + 1);
            setValueKeepCaret(nv3, start);
        }
    }

    var settled = false;
    function finish(status) {
        if (settled) return;
        settled = true;
        textInputValue = input.value || "";
        textInputStatus = status;
        text_input_destroy_ui();
    }

    btnOk.onclick = function (e) {
        e.preventDefault();
        e.stopPropagation();
        finish("ready");
    };
    btnCancel.onclick = function (e) {
        e.preventDefault();
        e.stopPropagation();
        finish("cancelled");
    };

    input.addEventListener("input", syncFromInput);
    input.addEventListener("keyup", syncFromInput);
    input.addEventListener("click", syncFromInput);
    input.addEventListener("select", syncFromInput);

    // Pegar nativo
    textInputPasteHandler = function (e) {
        if (textInputStatus !== "open") return;
        // dejar que el textarea lo maneje si tiene foco
        setTimeout(syncFromInput, 0);
    };
    input.addEventListener("paste", textInputPasteHandler);

    // Teclado manual (por si GM roba eventos)
    textInputKeyHandler = function (e) {
    if (textInputStatus !== "open" || !textInputRef) return;

    var ctrl = e.ctrlKey || e.metaKey;
    var input = textInputRef;

    // Asegurarnos de que el textarea tiene el foco
    try { input.focus(); } catch (err) {}

    // =====================================================
    //  Ctrl+A → seleccionar todo
    // =====================================================
    if (ctrl && (e.key === "a" || e.key === "A")) {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();

        input.setSelectionRange(0, input.value.length);
        return;
    }

    // =====================================================
    //  Ctrl+C → copiar
    // =====================================================
    if (ctrl && (e.key === "c" || e.key === "C")) {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();

        var s = input.selectionStart | 0;
        var en = input.selectionEnd | 0;
        var selected = (input.value || "").substring(s, en);

        if (selected) {
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(selected).catch(function () {});
            } else {
                // Fallback viejo
                try {
                    var ta = document.createElement("textarea");
                    ta.value = selected;
                    document.body.appendChild(ta);
                    ta.select();
                    document.execCommand("copy");
                    document.body.removeChild(ta);
                } catch (err) {}
            }
        }
        return;
    }

    // =====================================================
    //  Ctrl+X → cortar
    // =====================================================
    if (ctrl && (e.key === "x" || e.key === "X")) {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();

        var s2 = input.selectionStart | 0;
        var en2 = input.selectionEnd | 0;
        var selected2 = (input.value || "").substring(s2, en2);

        if (selected2) {
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(selected2).catch(function () {});
            }
            deleteSelectionOrChar(true);
            syncFromInput();
        }
        return;
    }

    // =====================================================
    //  Ctrl+V → pegar
    // =====================================================
    if (ctrl && (e.key === "v" || e.key === "V")) {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();

        if (navigator.clipboard && navigator.clipboard.readText) {
            navigator.clipboard.readText()
                .then(function (txt) {
                    replaceSelection(String(txt || ""));
                    syncFromInput();
                })
                .catch(function () {
                    console.warn("No se pudo leer el portapapeles");
                });
        }
        return;
    }

    // =====================================================
    //  Enter = OK
    // =====================================================
    if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        finish("ready");
        return;
    }

    // =====================================================
    //  Escape = Cancel
    // =====================================================
    if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        finish("cancelled");
        return;
    }

    // =====================================================
    //  Backspace
    // =====================================================
    if (e.key === "Backspace") {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        deleteSelectionOrChar(true);
        return;
    }

    // =====================================================
    //  Delete
    // =====================================================
    if (e.key === "Delete") {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        deleteSelectionOrChar(false);
        return;
    }

    // =====================================================
    //  Caracter normal
    // =====================================================
    if (!ctrl && !e.altKey && e.key && e.key.length === 1) {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        replaceSelection(e.key);
    }
};

    window.addEventListener("keydown", textInputKeyHandler, true);
    document.addEventListener("keydown", textInputKeyHandler, true);

    setTimeout(function () {
        try {
            input.focus();
            input.setSelectionRange(input.value.length, input.value.length);
        } catch (err) {}
    }, 30);
}

function text_input_destroy_ui() {
    if (textInputKeyHandler) {
        window.removeEventListener("keydown", textInputKeyHandler, true);
        document.removeEventListener("keydown", textInputKeyHandler, true);
        textInputKeyHandler = null;
    }
    if (textInputRef && textInputPasteHandler) {
        try { textInputRef.removeEventListener("paste", textInputPasteHandler); } catch (e) {}
        textInputPasteHandler = null;
    }
    if (textInputCanvas) {
        textInputCanvas.style.pointerEvents = textInputOldPointerEvents || "";
        textInputCanvas = null;
    }
    if (textInputElement && textInputElement.parentNode) {
        textInputElement.parentNode.removeChild(textInputElement);
    }
    textInputElement = null;
    textInputRef = null;
}

function text_input_get_live_value() {
    if (textInputRef) return String(textInputRef.value || "");
    return String(textInputValue || "");
}
function text_input_get_status() { return String(textInputStatus || "idle"); }
function text_input_is_ready() { return textInputStatus === "ready" ? 1 : 0; }
function text_input_was_cancelled() { return textInputStatus === "cancelled" ? 1 : 0; }
function text_input_get_value() { return String(textInputValue || ""); }
function text_input_clear() {
    textInputValue = "";
    textInputStatus = "idle";
    text_input_destroy_ui();
}


// =====================================================
//  ZIP IMPORT (Web)
// =====================================================
// =====================================================
//  ZIP IMPORT (Web) — compatible Opera / Safari / Chrome
// =====================================================
var zipFiles = [];
var zipStatus = "idle";
var zipError = "";

function zip_open() {
    zipFiles = [];
    zipStatus = "open";
    zipError = "";

    var old = document.getElementById("gm_zip_input");
    if (old && old.parentNode) {
        try { old.parentNode.removeChild(old); } catch (e) {}
    }

    var input = document.createElement("input");
    input.type = "file";
    input.accept = ".zip,application/zip,application/x-zip-compressed";
    input.id = "gm_zip_input";
    input.multiple = false;

    input.style.position = "fixed";
    input.style.left = "0";
    input.style.top = "0";
    input.style.width = "100%";
    input.style.height = "100%";
    input.style.opacity = "0.02";
    input.style.zIndex = "2147483647";
    input.style.display = "block";
    input.style.pointerEvents = "auto";
    input.style.border = "0";
    input.style.padding = "0";
    input.style.margin = "0";

    document.body.appendChild(input);

    var settled = false;

    function cleanupInput() {
        try {
            input.style.pointerEvents = "none";
            input.style.opacity = "0";
            input.style.display = "none";
        } catch (e1) {}
        setTimeout(function () {
            try {
                if (input.parentNode) input.parentNode.removeChild(input);
            } catch (e2) {}
        }, 300);
    }

    function finishCancel(reason) {
        if (settled) return;
        settled = true;
        zipFiles = [];
        zipStatus = "cancelled";
        zipError = String(reason || "cancelled");
        cleanupInput();
    }

    function finishReady(list) {
        if (settled) return;
        settled = true;
        zipFiles = list || [];
        zipStatus = "ready";
        zipError = "";
        cleanupInput();
    }

    input.addEventListener("cancel", function () {
        finishCancel("cancel event");
    });

    function onPicked(ev) {
        if (settled) return;
        if (zipStatus === "ready" || zipStatus === "cancelled") return;

        var files = input.files;
        if (!files || files.length === 0) {
            finishCancel("no files");
            return;
        }

        zipStatus = "loading";
        zipError = "";

        var file = files[0];

        var readBuf;
        if (file.arrayBuffer) {
            readBuf = file.arrayBuffer();
        } else {
            readBuf = new Promise(function (resolve, reject) {
                var r = new FileReader();
                r.onload = function () { resolve(r.result); };
                r.onerror = reject;
                r.readAsArrayBuffer(file);
            });
        }

        readBuf
            .then(function (ab) {
                return parseZipToDataURLs(new Uint8Array(ab));
            })
            .then(function (list) {
                if (!list || list.length === 0) {
                    finishCancel("empty zip or unsupported compression (use Store)");
                    return;
                }
                finishReady(list);
            })
            .catch(function (err) {
                finishCancel(err && err.message ? err.message : String(err));
            });
    }

    input.addEventListener("change", onPicked);
    input.addEventListener("input", onPicked);

    setTimeout(function () {
        try { input.focus(); } catch (e3) {}
        try { input.click(); } catch (e4) {}
    }, 0);
}

function inflateRaw(dataU8) {
    return new Promise(function (resolve, reject) {
        if (typeof DecompressionStream === "undefined") {
            reject(new Error("DecompressionStream not supported"));
            return;
        }
        try {
            var ds = new DecompressionStream("deflate-raw");
            var blob = new Blob([dataU8]);
            var stream = blob.stream().pipeThrough(ds);
            new Response(stream).arrayBuffer().then(function (ab) {
                resolve(new Uint8Array(ab));
            }).catch(reject);
        } catch (e) {
            reject(e);
        }
    });
}

function findEOCD(u8) {
    for (var i = u8.length - 22; i >= 0; i--) {
        if (u8[i] === 0x50 && u8[i + 1] === 0x4b && u8[i + 2] === 0x05 && u8[i + 3] === 0x06) {
            return i;
        }
    }
    return -1;
}

function parseZipToDataURLs(u8) {
    return new Promise(function (resolve) {
        var list = [];
        var view = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);

        var eocd = findEOCD(u8);
        if (eocd < 0) {
            resolve(list);
            return;
        }

        var totalEntries = view.getUint16(eocd + 10, true);
        var centralOffset = view.getUint32(eocd + 16, true);
        var offset = centralOffset;
        var index = 0;

        function nextEntry() {
            if (index >= totalEntries) {
                resolve(list);
                return;
            }

            if (offset + 46 > u8.length) {
                resolve(list);
                return;
            }

            var sig = view.getUint32(offset, true);
            if (sig !== 0x02014b50) {
                resolve(list);
                return;
            }

            var method = view.getUint16(offset + 10, true);
            var compSize = view.getUint32(offset + 20, true);
            var nameLen = view.getUint16(offset + 28, true);
            var extraLen = view.getUint16(offset + 30, true);
            var commentLen = view.getUint16(offset + 32, true);
            var localHeaderOffset = view.getUint32(offset + 42, true);

            var nameBytes = u8.subarray(offset + 46, offset + 46 + nameLen);
            var name = "";
            try {
                name = new TextDecoder("utf-8").decode(nameBytes).replace(/\\/g, "/");
            } catch (e) {
                name = "file_" + index;
            }

            offset += 46 + nameLen + extraLen + commentLen;
            index++;

            if (name.charAt(name.length - 1) === "/") {
                nextEntry();
                return;
            }

            var lh = localHeaderOffset;
            if (lh + 30 > u8.length) {
                nextEntry();
                return;
            }
            if (view.getUint32(lh, true) !== 0x04034b50) {
                nextEntry();
                return;
            }

            var lNameLen = view.getUint16(lh + 26, true);
            var lExtraLen = view.getUint16(lh + 28, true);
            var dataStart = lh + 30 + lNameLen + lExtraLen;
            var compData = u8.subarray(dataStart, dataStart + compSize);

            function pushData(outData) {
                var blob = new Blob([outData]);
                var r = new FileReader();
                r.onload = function () {
                    list.push({
                        name: name.split("/").pop(),
                        path: name,
                        dataUrl: r.result
                    });
                    nextEntry();
                };
                r.onerror = function () { nextEntry(); };
                r.readAsDataURL(blob);
            }

            if (method === 0) {
                pushData(compData);
            } else if (method === 8) {
                inflateRaw(compData).then(pushData).catch(function () {
                    nextEntry();
                });
            } else {
                nextEntry();
            }
        }

        nextEntry();
    });
}

function zip_get_status() { return String(zipStatus || "idle"); }
function zip_get_error() { return String(zipError || ""); }
function zip_is_ready() { return zipStatus === "ready" ? 1.0 : 0.0; }
function zip_was_cancelled() { return zipStatus === "cancelled" ? 1.0 : 0.0; }
function zip_is_loading() { return zipStatus === "loading" ? 1.0 : 0.0; }
function zip_file_count() { return zipFiles.length; }

function zip_get_name(index) {
    index = Number(index);
    if (index < 0 || index >= zipFiles.length) return "";
    return zipFiles[index].name;
}
function zip_get_path(index) {
    index = Number(index);
    if (index < 0 || index >= zipFiles.length) return "";
    return zipFiles[index].path;
}
function zip_get_data(index) {
    index = Number(index);
    if (index < 0 || index >= zipFiles.length) return "";
    return zipFiles[index].dataUrl;
}
function zip_clear() {
    zipFiles = [];
    zipStatus = "idle";
    zipError = "";
}
// =====================================================
//  ZIP DOWNLOAD (Store method)
// =====================================================
function downloadZipFile(filename, filesJson) {
    try {
        var files = JSON.parse(filesJson || "[]");
        var localFiles = [];
        var offset = 0;
        var central = [];

        function u16(n) { return [n & 255, (n >> 8) & 255]; }
        function u32(n) {
            return [n & 255, (n >> 8) & 255, (n >> 16) & 255, (n >> 24) & 255];
        }
        function crc32(arr) {
            var table = downloadZipFile._crcTable;
            if (!table) {
                table = new Uint32Array(256);
                for (var i = 0; i < 256; i++) {
                    var c = i;
                    for (var k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
                    table[i] = c >>> 0;
                }
                downloadZipFile._crcTable = table;
            }
            var crc = 0 ^ (-1);
            for (var i = 0; i < arr.length; i++) {
                crc = (crc >>> 8) ^ table[(crc ^ arr[i]) & 255];
            }
            return (crc ^ (-1)) >>> 0;
        }
        function encodePath(path) {
            return new TextEncoder().encode(path.replace(/\\/g, "/"));
        }
        function toBytes(file) {
            if (file.binary == 1 || file.binary === true) {
                var s = String(file.data || "");
                var b64 = s;
                var comma = s.indexOf(",");
                if (comma >= 0) b64 = s.substring(comma + 1);
                var bin = atob(b64);
                var out = new Uint8Array(bin.length);
                for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
                return out;
            } else {
                return new TextEncoder().encode(String(file.data || ""));
            }
        }

        for (var i = 0; i < files.length; i++) {
            var pathBytes = encodePath(files[i].path || ("file_" + i));
            var data = toBytes(files[i]);
            var crc = crc32(data);
            var nameLen = pathBytes.length;
            var size = data.length;

            var local = [];
            local.push(0x50,0x4b,0x03,0x04);
            local.push(20,0);
            local.push(0,0);
            local.push(0,0);
            local.push(0,0,0,0);
            local = local.concat(u32(crc));
            local = local.concat(u32(size));
            local = local.concat(u32(size));
            local = local.concat(u16(nameLen));
            local = local.concat(u16(0));
            for (var n = 0; n < nameLen; n++) local.push(pathBytes[n]);
            for (var d = 0; d < size; d++) local.push(data[d]);

            central.push({
                offset: offset,
                crc: crc,
                size: size,
                pathBytes: pathBytes
            });

            for (var j = 0; j < local.length; j++) localFiles.push(local[j]);
            offset += local.length;
        }

        var centralStart = offset;
        var centralArr = [];
        for (var i = 0; i < central.length; i++) {
            var c = central[i];
            var nameLen = c.pathBytes.length;
            var rec = [];
            rec.push(0x50,0x4b,0x01,0x02);
            rec.push(20,0,20,0);
            rec.push(0,0);
            rec.push(0,0);
            rec.push(0,0,0,0);
            rec = rec.concat(u32(c.crc));
            rec = rec.concat(u32(c.size));
            rec = rec.concat(u32(c.size));
            rec = rec.concat(u16(nameLen));
            rec = rec.concat(u16(0));
            rec = rec.concat(u16(0));
            rec = rec.concat(u16(0));
            rec = rec.concat(u16(0));
            rec = rec.concat(u32(0));
            rec = rec.concat(u32(c.offset));
            for (var n = 0; n < nameLen; n++) rec.push(c.pathBytes[n]);
            for (var j = 0; j < rec.length; j++) centralArr.push(rec[j]);
        }
        offset += centralArr.length;

        var eocd = [];
        eocd.push(0x50,0x4b,0x05,0x06);
        eocd.push(0,0,0,0);
        eocd = eocd.concat(u16(central.length));
        eocd = eocd.concat(u16(central.length));
        eocd = eocd.concat(u32(centralArr.length));
        eocd = eocd.concat(u32(centralStart));
        eocd = eocd.concat(u16(0));

        var all = new Uint8Array(localFiles.length + centralArr.length + eocd.length);
        all.set(localFiles, 0);
        all.set(centralArr, localFiles.length);
        all.set(eocd, localFiles.length + centralArr.length);

        var blob = new Blob([all], { type: "application/zip" });
        var url = URL.createObjectURL(blob);

        // === Parte importante para Safari / Chrome ===
        var a = document.getElementById("gm_download_link");
        if (!a) {
            a = document.createElement("a");
            a.id = "gm_download_link";
            a.style.display = "none";
            document.body.appendChild(a);
        }

        a.href = url;
        a.download = filename || "save_export.zip";
        
        // Forzar el click de forma más compatible
        a.click();

        // Limpieza
        setTimeout(function () {
            URL.revokeObjectURL(url);
        }, 2500);

        return 1;
    } catch (e) {
        console.error(e);
        return 0;
    }
}

window._ads_result = -1;

function ads_web_is_ready() {
    return 1;
}

function ads_web_show_rewarded() {
    window._ads_result = -1;
    setTimeout(function () {
        ads_web_finish(1);
    }, 2000);
}

function ads_web_finish(success) {
    window._ads_result = success ? 1 : 0;

    if (typeof gml_Script_gmcallback_ads_finished === "function") {
        gml_Script_gmcallback_ads_finished(success ? 1 : 0);
    }
}

function ads_web_poll_result() {
    var r = window._ads_result;
    if (r === -1 || typeof r === "undefined") return -1;
    window._ads_result = -1;
    return r;
}

